class Solution {
    public int getMinDistance(int[] nums,int target,int start){
        int answer=Integer.MAX_VALUE;
        for(int i=0;i<nums.length;i++)if(nums[i]==target)answer=Math.min(answer,Math.abs(i-start));
        return answer;
    }
}

code.cpp:
class Solution {
    public: int getMinDistance(vector<int>& nums,int target,int start){
        int answer=INT_MAX;
        for(int i=0;i<(int)nums.size();++i)if(nums[i]==target)answer=min(answer,abs(i-start));
        return answer;
    }
};
